ext = 'kode'

lang = function (l)
{
    return ext = l
}

ranges = function (s)
{
    return kulur.ranges(s,ext)
}

dissect = function (c)
{
    return kulur.dissect(kstr.lines(c),ext)
}

parse = function (c, e)
{
    return kulur.parse(kstr.lines(c),(e != null ? e : ext))
}
